// Generated by Cypress Author on 2026-10-11.
import { meResponse, minimalMeResponse } from '../../cypress/fixtures/me.ts';
import { stubAvatar, waitForAvatar } from '../../cypress/support/avatar.ts';
import CurrentUser from './CurrentUser.tsx';

const card = '[data-cy="current-user"]';

describe('<CurrentUser />', () => {
  beforeEach(() => {
    stubAvatar();
  });

  describe('when the profile loads', () => {
    beforeEach(() => {
      cy.intercept('GET', '/api/me', { body: meResponse }).as('me');
    });

    it('greets the user and summarises their account', () => {
      cy.mount(<CurrentUser />);
      cy.wait('@me');

      cy.get(card).within(() => {
        cy.contains('h2', 'Hi, Maria Ivanova!').should('be.visible');
        cy.contains('Premium').should('be.visible');
        cy.contains('Bulgaria').should('be.visible');
        cy.contains('1,234 followers').should('be.visible');
      });
    });

    it('clicks "My profile" → opens the profile dialog, Close → hides it', () => {
      cy.mount(<CurrentUser />);
      cy.wait('@me');

      cy.get('[data-cy="my-profile-button"]').click();
      cy.get('[role="dialog"]').should('be.visible').and('contain.text', 'maria@example.com');

      cy.contains('[role="dialog"] button', 'Close').click();
      cy.get('[role="dialog"]').should('not.exist');
    });

    it('Spotify did not share country and plan → the profile dialog offers to ask for them', () => {
      const onShare = cy.stub().as('onShare').resolves();
      cy.mount(<CurrentUser onShareMoreDetails={onShare} />);
      cy.wait('@me');

      cy.get('[data-cy="my-profile-button"]').click();
      cy.contains('[data-cy="share-more-details"] button', 'Allow').click();

      cy.get('@onShare').should('have.been.calledOnce');
    });

    it('matches the visual baseline', () => {
      cy.viewport(800, 400);
      cy.mount(<CurrentUser />);

      cy.contains('Hi, Maria Ivanova!').should('be.visible');
      waitForAvatar(card);
      cy.get(card).matchImage();
    });

    // Below MUI's `sm` breakpoint (600px) the avatar, greeting and button stack vertically.
    it('matches the visual baseline on a phone', () => {
      cy.viewport(400, 700);
      cy.mount(<CurrentUser />);

      cy.contains('Hi, Maria Ivanova!').should('be.visible');
      waitForAvatar(card);
      cy.get(card).matchImage();
    });
  });

  it('matches the visual baseline without a profile picture', () => {
    cy.intercept('GET', '/api/me', { body: minimalMeResponse });
    cy.viewport(800, 400);
    cy.mount(<CurrentUser />);

    cy.contains('Hi, quietlistener!').should('be.visible');
    cy.get(card).matchImage();
  });

  it('matches the visual baseline while loading', () => {
    // Hold the response back so the skeleton stays on screen.
    cy.intercept('GET', '/api/me', { body: meResponse, delay: 30_000 });
    cy.viewport(800, 400);
    cy.mount(<CurrentUser />);
    // Freeze the skeleton's pulse animation so the screenshot is deterministic.
    cy.document().then((doc) => {
      const style = doc.createElement('style');
      style.textContent = '.MuiSkeleton-root { animation: none !important; }';
      doc.head.appendChild(style);
    });

    cy.get(card).should('have.attr', 'aria-busy', 'true').matchImage();
  });

  it('shows a friendly error when Spotify fails', () => {
    cy.intercept('GET', '/api/me', { statusCode: 502, body: { error: 'spotify_error' } });
    cy.viewport(800, 400);
    cy.mount(<CurrentUser />);

    cy.get('[role="alert"]')
      .should('contain.text', "We couldn't load your profile")
      .and('contain.text', 'Spotify did not respond')
      .matchImage();
  });
});
